export function dollSourceSize(data,width,height){if(typeof data==='string'&&data.startsWith('data:image/svg+xml')){try{const encoded=data.slice(data.indexOf(',')+1),xml=data.slice(0,data.indexOf(',')).includes(';base64')?atob(encoded):decodeURIComponent(encoded),root=new DOMParser().parseFromString(xml,'image/svg+xml').documentElement,vb=(root.getAttribute('viewBox')||'').trim().split(/[ ,]+/).map(Number);if(vb.length===4&&vb[2]>0&&vb[3]>0&&(!root.getAttribute('width')||!root.getAttribute('height')||/%/.test((root.getAttribute('width')||'')+(root.getAttribute('height')||''))))return {sourceWidth:vb[2],sourceHeight:vb[3]}}catch{}}return {sourceWidth:width,sourceHeight:height}}
export async function readDollFile(file,withSize=false){
 if(file.size>10*1024*1024)throw Error('配件圖片上限為 10 MB');
 let data;
 if(/\.svg$/i.test(file.name)||file.type==='image/svg+xml'){
  const xml=await file.text();if(/<!DOCTYPE|<!ENTITY/i.test(xml))throw Error('SVG 不支援外部文件或實體');const doc=new DOMParser().parseFromString(xml,'image/svg+xml');if(doc.querySelector('parsererror')||doc.documentElement.localName!=='svg')throw Error('SVG 格式不正確');
  const tags=new Set(['svg','g','path','rect','circle','ellipse','line','polyline','polygon','defs','linearGradient','radialGradient','stop','clipPath','mask','title','desc','use','pattern','style']);
  const attrs=new Set(['xmlns','viewBox','width','height','x','y','fill','stroke','stroke-width','stroke-linecap','stroke-linejoin','d','points','cx','cy','r','rx','ry','x1','x2','y1','y2','opacity','fill-opacity','stroke-opacity','transform','id','class','offset','stop-color','stop-opacity','gradientUnits','gradientTransform','clip-path','mask','preserveAspectRatio','fill-rule','clip-rule','vector-effect','href','xlink:href','patternUnits','patternTransform','style']);
  const properties=new Set(['fill','stroke','stroke-width','stroke-linecap','stroke-linejoin','opacity','fill-opacity','stroke-opacity','stop-color','stop-opacity','fill-rule','clip-rule']);
  const safeValue=v=>!/(?:javascript:|data:|https?:|expression|@import)/i.test(v)&&[...v.matchAll(/url\(([^)]+)\)/gi)].every(m=>/^['"]?#[\w-]+['"]?$/.test(m[1].trim()));
  const cleanStyle=text=>text.split(';').map(decl=>{const split=decl.indexOf(':');if(split<0)return '';const key=decl.slice(0,split).trim(),value=decl.slice(split+1).trim();return properties.has(key)&&safeValue(value)?key+':'+value:''}).filter(Boolean).join(';');
  for(const el of [...doc.querySelectorAll('*')]){if(!tags.has(el.localName)){el.remove();continue}if(el.localName==='style'){el.textContent=[...el.textContent.matchAll(/([^{}]+)\{([^{}]*)\}/g)].map(m=>/^[.#\w\s,:>\-]+$/.test(m[1].trim())?m[1]+'{'+cleanStyle(m[2])+'}':'').join('')}
   for(const attr of [...el.attributes]){if(!attrs.has(attr.name)||!safeValue(attr.value)||((attr.name==='href'||attr.name==='xlink:href')&&!/^#[\w-]+$/.test(attr.value)))el.removeAttributeNode(attr);else if(attr.name==='style')el.setAttribute('style',cleanStyle(attr.value))}
  }
  if(!doc.querySelector('path,rect,circle,ellipse,line,polyline,polygon,use'))throw Error('SVG 沒有支援的圖形；請使用向量路徑或 PNG／WebP');doc.documentElement.setAttribute('xmlns','http://www.w3.org/2000/svg');data='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(new XMLSerializer().serializeToString(doc));
 }else if(isWebPFile(file)){
  data=await readWebPData(file);
 }else if(/\.png$/i.test(file.name)||file.type==='image/png'){
  const header=new Uint8Array(await file.slice(0,8).arrayBuffer());if([...header].join(',')!=='137,80,78,71,13,10,26,10')throw Error('檔案不是有效 PNG');data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('無法讀取圖片'));reader.readAsDataURL(file)});
 }else throw Error('只支援 PNG、WebP 或 SVG 配件');
 const dimensions=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>!img.naturalWidth||!img.naturalHeight?reject(Error('圖片必須具有有效長寬')):img.naturalWidth>10000||img.naturalHeight>10000?reject(Error('圖片尺寸不可超過 10000 像素')):resolve(dollSourceSize(data,img.naturalWidth,img.naturalHeight));img.onerror=()=>reject(Error('無法開啟圖片，請確認 PNG／WebP／SVG 內容'));img.src=data});return withSize?{image:data,...dimensions}:data;
}
